package br.com.admeclesial.interfaces.web.matrimonio; import br.com.admeclesial.application.matrimonio.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.util.*; @Controller public class MatrimonioWebController { final MatrimonioApplicationService s; final ProcessoMatrimonialApplicationService p; public MatrimonioWebController(MatrimonioApplicationService s,ProcessoMatrimonialApplicationService p){this.s=s;this.p=p;} @GetMapping("/processos-matrimoniais/{uuid}/registro") public String form(@PathVariable UUID uuid,Model m){m.addAttribute("processo",p.buscar(uuid));return "matrimonio/registro-form";} @PostMapping("/processos-matrimoniais/{uuid}/registro") public String salvar(@PathVariable UUID uuid,@RequestParam UUID celebracaoUuid,@RequestParam java.time.LocalDate dataRegistro,@RequestParam(required=false) String observacao){s.salvar(new MatrimonioRequest(uuid,celebracaoUuid,dataRegistro,observacao));return "redirect:/processos-matrimoniais/"+uuid;} }